function highestRankedKItems(grid, pricing, start, k) {
  const rows = grid.length;
  const cols = grid[0].length;
  const [low, high] = pricing;
  const dist = Array.from({ length: rows }, () => new Array(cols).fill(-1));
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const queue = [start];
  dist[start[0]][start[1]] = 0;
  const items = [];
  for (let head = 0; head < queue.length; head++) {
    const [r, c] = queue[head];
    const price = grid[r][c];
    if (price >= low && price <= high) {
      items.push([dist[r][c], price, r, c]);
    }
    for (const [dr, dc] of directions) {
      const nr = r + dr;
      const nc = c + dc;
      if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
      if (grid[nr][nc] === 0 || dist[nr][nc] !== -1) continue;
      dist[nr][nc] = dist[r][c] + 1;
      queue.push([nr, nc]);
    }
  }
  items.sort((a, b) => a[0] - b[0] || a[1] - b[1] || a[2] - b[2] || a[3] - b[3]);
  return items.slice(0, k).map(([, , r, c]) => [r, c]);
}

