function highestRankedKItems(grid, pricing, start, k) {
  const m = grid.length, n = grid[0].length;
  const INF = Number.MAX_SAFE_INTEGER;
  const d = grid.map(row => row.map(() => INF));
  d[start[0]][start[1]] = 0;
  // Relax every cell from its neighbours until nothing improves.
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) {
      if (grid[i][j] === 0) continue;
      for (const [a, b] of [[i - 1, j], [i + 1, j], [i, j - 1], [i, j + 1]]) {
        if (a >= 0 && a < m && b >= 0 && b < n && d[a][b] !== INF && d[a][b] + 1 < d[i][j]) { d[i][j] = d[a][b] + 1; changed = true; }
      }
    }
  }
  const pool = [];
  for (let i = 0; i < m; i++) for (let j = 0; j < n; j++)
    if (d[i][j] !== INF && grid[i][j] >= pricing[0] && grid[i][j] <= pricing[1]) pool.push({ i, j });
  const better = (x, y) => {
    const kx = [d[x.i][x.j], grid[x.i][x.j], x.i, x.j], ky = [d[y.i][y.j], grid[y.i][y.j], y.i, y.j];
    for (let t = 0; t < 4; t++) if (kx[t] !== ky[t]) return kx[t] < ky[t];
    return false;
  };
  const out = [];
  while (out.length < k && pool.length) {
    let best = 0;
    for (let t = 1; t < pool.length; t++) if (better(pool[t], pool[best])) best = t;
    out.push([pool[best].i, pool[best].j]);
    pool.splice(best, 1);
  }
  return out;
}

