function generate(rand, size) {
  const large = size === 'large';
  const m = large ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 5);
  const n = large ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 5);
  const maxPrice = large ? 100000 : 3 + Math.floor(rand() * 5);
  const wallRate = large ? 0.15 + rand() * 0.15 : rand() * 0.4;
  const emptyRate = rand() * 0.4;
  const grid = [];
  for (let i = 0; i < m; i++) {
    const row = [];
    for (let j = 0; j < n; j++) {
      const x = rand();
      if (x < wallRate) row.push(0);
      else if (x < wallRate + emptyRate * (1 - wallRate)) row.push(1);
      else row.push(2 + Math.floor(rand() * (maxPrice - 1)));
    }
    grid.push(row);
  }
  const r0 = Math.floor(rand() * m), c0 = Math.floor(rand() * n);
  if (grid[r0][c0] === 0) grid[r0][c0] = rand() < 0.5 ? 1 : 2 + Math.floor(rand() * (maxPrice - 1));
  const a = 2 + Math.floor(rand() * (maxPrice - 1)), b = 2 + Math.floor(rand() * (maxPrice - 1));
  const pricing = [Math.min(a, b), Math.max(a, b)];
  const k = 1 + Math.floor(rand() * (large && rand() < 0.5 ? 200 : m * n));
  return [grid, pricing, [r0, c0], Math.min(k, m * n)];
}
